// HasParentWith applies the HasEdge predicate on the "parent" edge with a given conditions (other predicates).
func HasParentWith(preds ...predicate.ClassificationRule) predicate.ClassificationRule {
	return predicate.ClassificationRule(func(s *sql.Selector) {
		step := newParentStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasOverrides applies the HasEdge predicate on the "overrides" edge.
func HasOverrides() predicate.ClassificationRule {
	return predicate.ClassificationRule(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, OverridesTable, OverridesColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

