// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ClassificationRule) predicate.ClassificationRule {
	return predicate.ClassificationRule(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ClassificationRule) predicate.ClassificationRule {
	return predicate.ClassificationRule(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ClassificationRule) predicate.ClassificationRule {
	return predicate.ClassificationRule(sql.NotPredicates(p))
}
